import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;

public class LineCountingOutputStreamTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static ByteArrayOutputStream sink;
    static LineCountingOutputStream counter;

    static void start() {
        sink = new ByteArrayOutputStream();
        counter = new LineCountingOutputStream(sink);
    }

    static String written() {
        return sink.toString(StandardCharsets.UTF_8).replace("\n", "<nl>");
    }

    public static void main(String[] args) {
        try {
            start();
            for (byte b : "a\nb\n".getBytes(StandardCharsets.UTF_8)) {
                counter.write(b);
            }
            counter.flush();
            check("count via write(int)", 2, counter.getLineCount());
            check("content via write(int)", "a<nl>b<nl>", written());

            start();
            counter.write("one\ntwo\nthree".getBytes(StandardCharsets.UTF_8));
            counter.flush();
            check("count via write(byte[])", 2, counter.getLineCount());
            check("content via write(byte[])", "one<nl>two<nl>three", written());

            start();
            byte[] data = "xx\nyy\nzz".getBytes(StandardCharsets.UTF_8);
            counter.write(data, 3, 3);
            counter.flush();
            check("count via write(byte[], off, len)", 1, counter.getLineCount());
            check("content via write(byte[], off, len)", "yy<nl>", written());

            start();
            counter.write("no newlines here".getBytes(StandardCharsets.UTF_8));
            counter.flush();
            check("count with no newlines", 0, counter.getLineCount());
            check("content with no newlines", "no newlines here", written());

            start();
            counter.flush();
            check("count after writing nothing", 0, counter.getLineCount());
        } catch (Exception e) {
            System.out.println("FAIL  stream threw " + e.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

